function planter(x, z, s = 1, parent = scene) {
  const g = new THREE.Group(); g.position.set(x, FY, z); g.scale.setScalar(s); parent.add(g);
  cyl(.24, .2, .55, M('#0f0f11', { roughness: .35, metalness: .3 }), 0, .275, 0, g); cyl(.245, .245, .025, BRASS, 0, .55, 0, g);
  const leafA = M('#2f6e3c', { roughness: .6 }), leafB = M('#3d8549', { roughness: .6 });
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * Math.PI * 2, r = .06 + (i % 3) * .05;
    const l = new THREE.Mesh(new THREE.SphereGeometry(.13, 10, 8), i % 2 ? leafA : leafB);
    l.scale.set(.9, 2.6, .35); l.position.set(Math.cos(a) * r, .85 + (i % 4) * .12, Math.sin(a) * r);
    l.rotation.set(Math.sin(a) * .5, -a, Math.cos(a) * .5); l.castShadow = true; g.add(l);
  }
}
