function floatingShelf(x, y, z, ry, len = 1.6, books = true) {
  const g = new THREE.Group(); g.position.set(x, FY + y, z); g.rotation.y = ry; scene.add(g);
  box(len, .045, .28, SHELF, 0, 0, 0, g);
  if (!books) return g;
  let px = -len / 2 + .08;
  while (px < len / 2 - .12) {
    if (Math.random() < .12) { // dekor obje
      cyl(.06, .05, .16, M(Math.random() < .5 ? '#e8e4dc' : '#2a2b2e', { roughness: .4 }), px + .07, .1, 0, g); px += .2; continue; }
    const n = 2 + (Math.random() * 6 | 0);
    for (let i = 0; i < n && px < len / 2 - .1; i++) { const bw = .035 + Math.random() * .03, bh = .17 + Math.random() * .09;
      box(bw, bh, .19, BOOKC[(Math.random() * BOOKC.length) | 0], px + bw / 2, .022 + bh / 2, .01, g); px += bw + .006; }
    px += .08 + Math.random() * .15;
  }
  return g;
}
