function trackRail(x1, z1, x2, z2, light = false) {
  const len = Math.hypot(x2 - x1, z2 - z1), hz = Math.abs(z2 - z1) < 1e-6, cx = (x1 + x2) / 2, cz = (z1 + z2) / 2, y = FY + H - .06;
  box(hz ? len : .05, .04, hz ? .05 : len, BLACK, cx, y, cz, scene, false);
  const n = Math.max(2, Math.round(len / 1.1));
  for (let i = 0; i < n; i++) { const t = (i + .5) / n, x = x1 + (x2 - x1) * t, z = z1 + (z2 - z1) * t;
    const head = cyl(.045, .055, .14, BLACK, x, y - .1, z, scene, 12); head.castShadow = false; head.rotation.z = (i % 2 ? .35 : -.35);
    const lens = cyl(.035, .035, .005, M('#fff3d8', { emissive: '#ffd9a0', emissiveIntensity: 1.2 }), x, y - .175, z, scene, 12); lens.castShadow = false; }
  if (light) { const sp = new THREE.SpotLight('#ffd6a3', 9, 7, .75, .55, 1.4); sp.position.set(cx, y - .1, cz); sp.target.position.set(cx, FY, cz); scene.add(sp, sp.target); }
}

