function bubbleSprite(icon = 'mail', badge = '3') {
  const c = document.createElement('canvas'); c.width = 256; c.height = 256; const g = c.getContext('2d');
  g.fillStyle = '#fff'; g.shadowColor = 'rgba(0,0,0,.25)'; g.shadowBlur = 12;
  g.beginPath(); g.roundRect(28, 28, 200, 150, 34); g.fill(); g.beginPath(); g.moveTo(100, 176); g.lineTo(128, 214); g.lineTo(156, 176); g.fill();
  g.shadowBlur = 0; g.strokeStyle = BLUE; g.fillStyle = BLUE; g.lineWidth = 9;
  if (icon === 'mail') { g.beginPath(); g.roundRect(70, 64, 116, 80, 10); g.stroke(); g.beginPath(); g.moveTo(72, 68); g.lineTo(128, 110); g.lineTo(184, 68); g.stroke(); }
  else if (icon === 'video') { g.beginPath(); g.roundRect(62, 62, 132, 86, 14); g.stroke(); g.beginPath(); g.moveTo(112, 82); g.lineTo(152, 105); g.lineTo(112, 128); g.closePath(); g.fill(); }
  else if (icon === 'text') { g.font = '900 64px Georgia, serif'; g.textAlign = 'center'; g.fillText('Aa', 128, 128); g.fillRect(84, 140, 88, 7); g.textAlign = 'left'; }
  else if (icon === 'plan') { g.beginPath(); g.roundRect(80, 52, 96, 112, 10); g.stroke(); g.fillRect(104, 44, 48, 18); [86, 112, 138].forEach((y, i) => { g.beginPath(); g.moveTo(96, y); g.lineTo(104, y + 8); g.lineTo(118, y - 8); g.stroke(); g.fillRect(126, y - 2, 36, 7); }); }
  else if (icon === 'ads') { g.beginPath(); g.moveTo(66, 150); g.lineTo(190, 150); g.stroke(); [[78, 120], [110, 95], [142, 110], [174, 70]].forEach(([x, y]) => g.fillRect(x - 10, y, 22, 150 - y)); }
  else if (icon === 'web') { g.font = '900 60px Consolas, monospace'; g.textAlign = 'center'; g.fillText('</>', 128, 124); g.textAlign = 'left'; }
  else if (icon === 'design') { g.beginPath(); g.ellipse(128, 104, 66, 50, 0, 0, 7); g.stroke(); [[100, 88, RED], [130, 76, '#e39a1e'], [158, 92, '#1f9d5c'], [106, 120, BLUE]].forEach(([x, y, c]) => { g.fillStyle = c; g.beginPath(); g.arc(x, y, 11, 0, 7); g.fill(); }); }
  if (badge) { g.fillStyle = RED; g.beginPath(); g.arc(196, 60, 28, 0, 7); g.fill(); g.fillStyle = '#fff'; g.font = '800 34px Inter, sans-serif'; g.textAlign = 'center'; g.fillText(badge, 196, 72); }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: t })); s.scale.set(.85, .85, 1); scene.add(s); return s;
}
