const KAPI = {};
function kapiTabelasi(oda, ad, x, z, ry) {
  const c = document.createElement('canvas'); c.width = 512; c.height = 96; const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
  const m = plane(1.05, .2, new THREE.MeshStandardMaterial({ map: t, emissive: '#ffffff', emissiveMap: t, emissiveIntensity: .35 }), x, FY + 2.48, z, 0, ry);
  const ciz = yazi => { const g = c.getContext('2d'); g.fillStyle = '#0d0d0f'; g.fillRect(0, 0, 512, 96); g.fillStyle = GOLD; g.fillRect(0, 88, 512, 8);
    let fs = 46; g.font = `800 ${fs}px Inter, sans-serif`; while (g.measureText(yazi).width > 480 && fs > 24) { fs -= 2; g.font = `800 ${fs}px Inter, sans-serif`; }
    g.fillStyle = '#f2eee6'; g.textAlign = 'center'; g.fillText(yazi, 256, 62); t.needsUpdate = true; };
  ciz(ad); (KAPI[oda] = KAPI[oda] || []).push(ciz); return m;
}
