// Canlı rozetler: çalışırken '…', son 24 saatte yeni dosya varsa sayısı
const bubbleState = {};
function setBubble(spr, icon, badge) {
  const key = icon + badge; if (bubbleState[icon] === key) return; bubbleState[icon] = key;
  const n = bubbleSprite(icon, badge); spr.material.map.dispose(); spr.material.map = n.material.map; spr.material.needsUpdate = true; scene.remove(n);
}
function updateBubbles() {
  if (!live) return;
  [['mail', bubble, 'mail'], ['mudur', mBubble, 'plan'], ['reklam', rBubble, 'ads'], ['metin', tBubble, 'text'], ['web', wBubble, 'web']].forEach(([k, spr, icon]) => {
    const run = live.gorevler.some(g => g.ajan === k && g.durum === 'calisiyor');
    const yeni = live.ajanlar[k].dosyalar.filter(f => Date.now() - f.zaman < 86400000).length;
    const bekleyen = live.gorevler.some(g => g.ajan === k && g.durum === 'bitti');
    setBubble(spr, icon, run ? '…' : bekleyen ? '!' : (yeni ? String(Math.min(yeni, 9)) : ''));
  });
}

// Kafanın üstünde ilerleme göstergesi
function progressSprite() {
  const c = document.createElement('canvas'); c.width = 640; c.height = 200;
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: t, depthTest: false, transparent: true, toneMapped: false, fog: false }));
  s.scale.set(2.3, .72, 1); s.renderOrder = 12; s.visible = false; scene.add(s); s.userData = { c, t, key: '' }; return s;
}
function drawProgress(spr, g, phase) {
  const { c, t } = spr.userData, x = c.getContext('2d'), W = c.width;
  x.clearRect(0, 0, W, c.height);
  x.fillStyle = 'rgba(255,255,255,.97)'; x.shadowColor = 'rgba(0,0,0,.25)'; x.shadowBlur = 14; x.beginPath(); x.roundRect(16, 16, W - 32, 168, 30); x.fill(); x.shadowBlur = 0;
  const pct = g.yuzde;
  x.fillStyle = BLUE; x.font = '800 64px Inter, sans-serif'; x.textBaseline = 'alphabetic';
  x.fillText(pct == null ? '…' : '%' + pct, 44, 92);
  x.fillStyle = '#6b7487'; x.font = '700 30px Inter, sans-serif';
  const lbl = (g.eylem || 'Çalışıyor'); x.fillText(lbl.length > 22 ? lbl.slice(0, 21) + '…' : lbl, pct == null ? 110 : (pct >= 100 ? 230 : pct >= 10 ? 200 : 165), 82);
  x.fillStyle = '#e8edf3'; x.beginPath(); x.roundRect(44, 118, W - 88, 30, 15); x.fill();
  if (pct == null) { const bw = (W - 88) * .3, bx = 44 + ((phase % 1) * (W - 88 + bw)) - bw; x.save(); x.beginPath(); x.roundRect(44, 118, W - 88, 30, 15); x.clip(); x.fillStyle = '#9fb2c8'; x.fillRect(bx, 118, bw, 30); x.restore(); }
  else { const g2 = x.createLinearGradient(44, 0, W - 44, 0); g2.addColorStop(0, BLUE); g2.addColorStop(1, '#2f8fd8'); x.fillStyle = g2; x.beginPath(); x.roundRect(44, 118, Math.max(30, (W - 88) * pct / 100), 30, 15); x.fill(); }
  t.needsUpdate = true;
}
const PROG = {};
function updateProgress() {
  if (!live) return;
  [['mail', -8.35, 3.25], ['mudur', 6, 4.15], ['reklam', 8.3, -4.6], ['metin', -1.95, -4.65], ['web', 5.7, -4.6]].concat(Object.entries(YZ_YER).map(([k, [x, z]]) => [k, x, z, 1])).forEach(([k, x, z, yz]) => {
    if (!live.ajanlar[k]) return;
    if (!PROG[k]) { PROG[k] = progressSprite(); PROG[k].position.set(x, FY + (yz ? 2.95 : 2.4), z); PROG[k].userData.y0 = FY + (yz ? 2.95 : 2.4); PROG[k].userData.b = [x, z]; }
    const off = MASA[k] ? MASA[k].g.position : { x: 0, z: 0 }; PROG[k].position.x = PROG[k].userData.b[0] + off.x; PROG[k].position.z = PROG[k].userData.b[1] + off.z; if (gizliAjan(k)) { PROG[k].visible = false; return; }
    const g = live.gorevler.find(j => j.ajan === k && j.durum === 'calisiyor');
    PROG[k].visible = !!g; PROG[k].userData.g = g || null;
    const bub = { mail: bubble, mudur: mBubble, reklam: rBubble, metin: tBubble, web: wBubble }[k]; if (bub) bub.visible = !g;
    if (g) drawProgress(PROG[k], g, 0);
  });
}

