const ETIKET = {};
function label(text, sub, x, y, z, active = false, scale = 1, sp) {
  const c = sp ? sp.userData.c : document.createElement('canvas'); c.width = 640; c.height = 170; const g = c.getContext('2d'); g.clearRect(0, 0, 640, 170);
  let fs = 50; g.font = `800 ${fs}px Inter, sans-serif`; while (g.measureText(text).width > 560 && fs > 30) { fs -= 2; g.font = `800 ${fs}px Inter, sans-serif`; }
  g.fillStyle = 'rgba(12,12,14,.9)'; g.beginPath(); g.roundRect(8, 8, 624, 150, 30); g.fill(); g.strokeStyle = active ? 'rgba(212,166,74,.8)' : 'rgba(120,120,125,.5)'; g.lineWidth = 3; g.stroke();
  g.fillStyle = active ? GOLD : '#55565b'; g.fillRect(8, 30, 10, 106);
  g.fillStyle = active ? '#f3eee4' : '#8c8b88'; g.font = `800 ${fs}px Inter, sans-serif`; g.fillText(text, 48, 76);
  let fs2 = 32; g.font = `700 ${fs2}px Inter, sans-serif`; while (g.measureText(sub).width > 570 && fs2 > 20) { fs2 -= 2; g.font = `700 ${fs2}px Inter, sans-serif`; }
  g.fillStyle = active ? '#4cc38a' : '#77767a'; g.fillText(sub, 48, 128);
  if (sp) { sp.material.map.needsUpdate = true; return sp; }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace;
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: t, depthTest: false })); s.scale.set(3.4 * scale, .9 * scale, 1); s.position.set(x, y, z); s.renderOrder = 10; s.userData = { c, text, sub, active }; scene.add(s); return s;
}
