const zaman = ms => { const d = (Date.now() - ms) / 1000; if (d < 60) return 'az önce'; if (d < 3600) return Math.floor(d / 60) + ' dk önce'; if (d < 86400) return Math.floor(d / 3600) + ' sa önce'; return new Date(ms).toLocaleString('tr-TR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }); };
const boyut = b => b > 1048576 ? (b / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(b / 1024)) + ' KB';

const EKLER = {}; // ajan -> [{ad, yol, url, tur, kareler:[], durum}]
const grupAdi = () => { const d = new Date(), z = n => String(n).padStart(2, '0'); return `${d.getFullYear()}-${z(d.getMonth() + 1)}-${z(d.getDate())}_${z(d.getHours())}${z(d.getMinutes())}${z(d.getSeconds())}`; };
async function yukle(k, blob, ad, grup) {
  const r = await fetch(`/api/yukle?ajan=${k}&ad=${encodeURIComponent(ad)}&grup=${grup}`, { method: 'POST', headers: { 'X-Ofis-Token': OFIS_TOKEN, 'Content-Type': 'application/octet-stream' }, body: blob });
  const j = await r.json().catch(() => ({})); if (!r.ok) throw new Error(j.hata || 'Yüklenemedi'); return j;
}
// Videodan eşit aralıklı kareler çıkar (ajan videoyu izleyemez, kareleri görür)
let duraklat = 0;
function kareCikar(file, adet = 10) {
  duraklat++;
  return new Promise((ok0) => { const ok = x => { duraklat = Math.max(0, duraklat - 1); ok0(x); };
    const v = document.createElement('video'); v.muted = true; v.preload = 'auto'; v.src = URL.createObjectURL(file);
    const kareler = []; let i = 0, bitti = false;
    const bitir = () => { if (bitti) return; bitti = true; try { URL.revokeObjectURL(v.src); } catch {} ok(kareler); };
    setTimeout(bitir, 30000);
    v.onloadedmetadata = () => {
      const dur = v.duration || 1, W = Math.min(1280, v.videoWidth || 1280), H = Math.round(W * (v.videoHeight || 720) / (v.videoWidth || 1280));
      const c = document.createElement('canvas'); c.width = W; c.height = H; const g = c.getContext('2d');
      const zamanlar = Array.from({ length: adet }, (_, n) => Math.min(dur - 0.01, (n + 0.5) * dur / adet));
      let bekle = null;
      const sonraki = () => { clearTimeout(bekle); if (i >= zamanlar.length) return bitir(); bekle = setTimeout(bitir, 5000); v.currentTime = zamanlar[i]; };
      v.onseeked = () => { g.drawImage(v, 0, 0, W, H); c.toBlob(b => { kareler.push({ blob: b, t: zamanlar[i] }); i++; sonraki(); }, 'image/jpeg', .9); };
      v.onerror = bitir; sonraki();
    };
    v.onerror = bitir;
  });
}
async function dosyaEkle(k, files, alan) {
  if (!online) { alan.querySelector('.ekmsg').textContent = 'Dosya eklemek için ofisi bilgisayarınızda açın (ofisi-baslat.bat).'; return; }
  EKLER[k] = EKLER[k] || []; const grup = EKLER[k].grup || (EKLER[k].grup = grupAdi());
  for (const f of files) {
    const e = { ad: f.name, tur: f.type.startsWith('video') ? 'video' : f.type.startsWith('image') ? 'gorsel' : 'dosya', durum: 'yükleniyor…', yol: null, kareler: [], onizleme: URL.createObjectURL(f) };
    EKLER[k].push(e); ekleriCiz(k);
    try {
      const j = await yukle(k, f, f.name, grup); e.yol = j.yol;
      if (e.tur === 'video') { e.durum = 'kareler çıkarılıyor…'; ekleriCiz(k);
        const ks = await kareCikar(f, 10); const kok = f.name.replace(/\.[^.]+$/, '');
        for (let n = 0; n < ks.length; n++) { const kj = await yukle(k, ks[n].blob, `${kok}_kare${String(n + 1).padStart(2, '0')}.jpg`, grup); e.kareler.push(kj.yol); }
        e.durum = e.kareler.length ? `${e.kareler.length} kare` : 'kare çıkarılamadı, sadece video gider'; }
      else e.durum = 'hazır';
    } catch (err) { e.durum = '⚠ ' + err.message; }
    ekleriCiz(k);
  }
}
function ekleriCiz(k) {
  const el = panel.querySelector(`.gv[data-k="${k}"] .eklist`); if (!el) return;
  const list = EKLER[k] || [];
  el.innerHTML = list.map((e, i) => `<div class="ekc">${e.tur === 'gorsel' ? `<img src="${e.onizleme}">` : e.tur === 'video' ? `<video src="${e.onizleme}" muted></video>` : '<span>📄</span>'}<span title="${esc(e.ad)}">${esc(e.ad)}</span><small>${esc(e.durum)}</small><button data-x="${i}" title="Kaldır">×</button></div>`).join('');
  el.querySelectorAll('button[data-x]').forEach(b => b.onclick = () => { list.splice(+b.dataset.x, 1); ekleriCiz(k); });
}
const ekYollari = k => (EKLER[k] || []).filter(e => e.yol).flatMap(e => [e.yol, ...e.kareler]);

async function isle(id, a, el, btn) {
  const msg = el.querySelector(':scope > .msg');
  if (a === 'revize-ac') { el.querySelector('.rev').classList.add('open'); el.querySelector('.rev textarea').focus(); return; }
  if (a === 'revize-kapat') { el.querySelector('.rev').classList.remove('open'); return; }
  if (a === 'iptal' && !confirmInline(btn, 'Emin misiniz? Tekrar basın')) return;
  const yol = { onayla: 'onayla', revize: 'revize', tekrar: 'tekrar', iptal: 'iptal', klasor: 'klasor', dagit: 'dagit', ata: 'ata' }[a];
  const govde = a === 'revize' ? { not: el.querySelector('.rev textarea').value } : a === 'ata' ? { ajan: el.querySelector('.ata select').value } : {};
  if (a === 'ata' && !govde.ajan) { msg.className = 'msg err'; msg.textContent = 'Önce görevi devralacak ajanı seçin.'; return; }
  el.querySelectorAll('button').forEach(b => b.disabled = true);
  try {
    const r = await fetch(`/api/gorev/${id}/${yol}`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Ofis-Token': OFIS_TOKEN }, body: JSON.stringify(govde) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) { msg.className = 'msg err'; msg.textContent = j.hata || 'İşlem yapılamadı.'; el.querySelectorAll('button').forEach(b => b.disabled = false); return; }
    msg.className = 'msg ok';
    msg.textContent = { ata: `Görev ${AJAN_AD[j.ajan] || j.ajan} ajanına devredildi ve başladı.`, dagit: `Plan onaylandı: ${j.adim} adım ajanlara dağıtılıyor.`, onayla: `Onaylandı. ${j.dosyalar?.length || 0} dosya "${j.klasor}" klasörüne kopyalandı ve klasör açıldı.`, revize: 'Düzeltme isteği ajana gönderildi.', tekrar: 'Görev yeniden başlatıldı.', iptal: 'İptal edildi.', klasor: 'Klasör açıldı.' }[a];
    const panelEl = panel.querySelector('.jobs'); if (panelEl) panelEl.dataset.sig = '';
    setTimeout(poll, 400);
  } catch { msg.className = 'msg err'; msg.textContent = 'Ofis sunucusuna ulaşılamadı.'; el.querySelectorAll('button').forEach(b => b.disabled = false); }
}

